import InputOTP from "@marko-ui/shadcn/ui/input-otp/input-otp.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";

<Field class="w-fit">
  <FieldLabel for="digits-only">Digits Only</FieldLabel>
  <InputOTP id="digits-only" length=6 pattern="^\d+$"/>
</Field>

import InputOTP from "@marko-ui/shadcn/ui/input-otp/input-otp.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";

<Field class="mx-auto max-w-xs">
  <FieldLabel for="input-otp-rtl">رمز التحقق</FieldLabel>
  <InputOTP id="input-otp-rtl" length=6 defaultValue=["1","2","3","4","5","6"] dir="rtl"/>
</Field>
